patch:
--- a/src/data/repo.js
+++ b/src/data/repo.js
@@ -1,1 +1,6 @@
-module.exports = { find: (id) => { if (id < 0) throw new Error("bad id"); return { id }; } };
+module.exports = {
+  find: (id) => {
+    if (id < 0) throw Object.assign(new Error("bad id"), { code: "INVALID_ID" });
+    return { id };
+  },
+};
--- a/src/service/lookup.js
+++ b/src/service/lookup.js
@@ -1,2 +1,9 @@
-const repo = require("src/data/repo.js");
-module.exports = (id) => ({ ok: true, item: repo.find(id) });
+const repo = require("src/data/repo.js");
+module.exports = (id) => {
+  try {
+    return { ok: true, item: repo.find(id) };
+  } catch (error) {
+    if (error.code === "INVALID_ID") return { ok: false, code: error.code };
+    throw error;
+  }
+};

